  env.error("[RH] failed while loading dcs.lua: " .. tostring(__err))
  trigger.action.outText("ROTORHEADS failed while loading dcs.lua: " .. tostring(__err), 60)
  return
end end
-- ===== world.lua =====
do local __ok, __err = pcall(function()
RH = RH or {}

local util = RH.util

-- Snapshot of every ground group, ship, and static. This is what comes back on the next
-- mission start, and what the server hook writes into RH_Editor.miz for the Mission Editor.
local world = {}
RH.world = world

-- Recreated by other campaign systems. Saving them here would spawn a second copy.
local EXCLUDE_PREFIXES = {
  "Garrison ",
  "Convoy ",
  "Factory troops ",
  "Insurgents",
  "Havoc",
  "Red CAP",
  "Paratroopers",
  "Supply convoy",
  "Convoy escort",
  "Mi-26 ",
  "RH Pilot ",
}

function world.excluded(name)
  if type(name) ~= "string" or name == "" then return true end
  for _, prefix in ipairs(EXCLUDE_PREFIXES) do
    if name:sub(1, #prefix) == prefix then return true end
  end
  -- The template itself stays in the mission file. A built copy is named with # or -1.
  if name:sub(1, 7) == "RH_TPL_" and not string.find(name, "#", 1, true) and not string.find(name, "%-%d+$") then
    return true
  end
  return false
end

function world.farpOwned(name)
  if type(name) ~= "string" or not RH.state or not RH.state.farps then return false end
  for farpName in pairs(RH.state.farps) do
    if name == farpName or name:sub(1, #farpName + 1) == farpName .. " " then return true end
  end
  return false
end

-- alive is a list of { name, x, y } already in the mission when it starts.
function world.plan(saved, alive)
  saved = saved or {}
  local desired = {}
  for _, obj in ipairs(saved.objects or {}) do
    if obj.name and not world.excluded(obj.name) then desired[obj.name] = obj end
  end
  local baseline = saved.baseline or {}
  local here = {}
  for _, obj in ipairs(alive or {}) do
    if obj.name and not world.excluded(obj.name) then here[obj.name] = obj end
  end
  local spawn, destroy, adopt, refresh = {}, {}, {}, {}
  for name, obj in pairs(desired) do
    if world.farpOwned(name) then
      -- The FARP spawner places the pad and its tent, depots, and Humvee.
    elseif not here[name] then
      spawn[#spawn + 1] = obj
    elseif obj.x and here[name].x and util.distance(obj, here[name]) > 25 then
      refresh[#refresh + 1] = obj
    end
  end
  for name in pairs(here) do
    if not desired[name] and not world.farpOwned(name) then
      if baseline[name] then destroy[#destroy + 1] = name else adopt[#adopt + 1] = name end
    end
  end
  local function byName(a, b)
    local an = type(a) == "table" and a.name or a
    local bn = type(b) == "table" and b.name or b
    return tostring(an) < tostring(bn)
  end
  table.sort(spawn, byName)
  table.sort(refresh, byName)
  table.sort(destroy)
  table.sort(adopt)
  return { spawn = spawn, destroy = destroy, adopt = adopt, refresh = refresh }
end

function world.capture()
  if not RH.dcs.snapshotGround then return false end
  local roster = RH.dcs.snapshotGround() or {}
  local state = RH.state.world or { baseline = {} }
  state.baseline = state.baseline or {}
  if not state.baselineReady then
    state.baseline = {}
    for _, obj in ipairs(roster) do
      if not world.excluded(obj.name) and not world.farpOwned(obj.name) then
        state.baseline[obj.name] = true
      end
    end
    state.baselineReady = true
  end
  local objects = {}
  for _, obj in ipairs(roster) do
    if not world.excluded(obj.name) then
      if world.farpOwned(obj.name) then obj.origin = "farp"
      elseif state.baseline[obj.name] then obj.origin = "baseline"
      else obj.origin = "runtime" end
      objects[#objects + 1] = obj
    end
  end
  table.sort(objects, function(a, b) return tostring(a.name) < tostring(b.name) end)
  state.objects = objects
  state.savedAt = RH.dcs.wallclock()
  RH.state.world = state
  local path = RH.dcs.savePath and RH.dcs.savePath("world.lua")
  if path and RH.dcs.writeFile then RH.dcs.writeFile(path, util.serialize(state)) end
  world._payload = util.serialize(state)
  return true
end

-- The server hook asks for this. It has file access even when the mission scripting sandbox does not.
function world.cachePayload()
  local ok, err = pcall(world.capture)
  if not ok then
    world._payload = "error: " .. tostring(err)
  end
  world._payload = world._payload or "error: nothing captured"
  return #world._payload
end

function world.payloadSlice(index, size)
  local text = world._payload or ""
  size = size or 4000
  index = index or 1
  local from = (index - 1) * size + 1
  return text:sub(from, from + size - 1)
end

function world.savedRoot()
  if not RH.dcs.filesEnabled or not RH.dcs.filesEnabled() then return nil end
  if not lfs or not lfs.writedir then return nil end
  local base = lfs.writedir()
  if type(base) ~= "string" or base == "" then return nil end
  if not base:match("[/\\]$") then base = base .. "\\" end
  return base
end

function world.fileExists(path)
  if type(path) ~= "string" or path == "" or not io then return false end
  local f = io.open(path, "rb")
  if not f then return false end
  f:close()
  return true
end

-- Prefer the mission the hook saw, then the configured test mission. Never read the editor copy back in.
function world.pickSource(root, hint, exists)
  exists = exists or world.fileExists
  local function accept(path)
    if type(path) ~= "string" then return nil end
    path = path:gsub("^%s+", ""):gsub("%s+$", "")
    if path == "" or path:lower():match("rh_editor%.miz$") then return nil end
    if exists(path) then return path end
    return nil
  end
  local chosen = accept(hint)
  if chosen then return chosen end
  return accept(root .. (RH.config.editorSource or "Missions\\RH Test.miz"))
end

function world.writeNote(text)
  local root = world.savedRoot()
  if not root or not RH.dcs.writeFile then return end
  RH.dcs.writeFile(root .. "Missions\\Rotorheads\\last_export.txt", text .. "\r\n")
  util.log("editor: %s", (text:gsub("\r\n", " | ")))
end

-- Builds Saved Games\DCS\Missions\RH_Editor.miz from the running mission plus the snapshot.
-- This runs in the mission script, which can already write files. The server hook cannot see the miz.
function world.exportEditor()
  local root = world.savedRoot()
  if not root then return end
  if not RH.miz or not RH.miz.exportFile then
    world.writeNote("Editor mission was not built: the mission packer is not loaded.")
    return
  end
  local hint = RH.dcs.readFile and RH.dcs.readFile(root .. "rotorheads\\active_mission.txt") or nil
  local src = world.pickSource(root, hint)
  local dest = root .. "Missions\\RH_Editor.miz"
  if not src then
    world.writeNote("Editor mission was not built. Put the mission at Saved Games\\DCS\\Missions\\RH Test.miz, or launch it so the hook can record the path.")
    return
  end
  local ok, err = RH.miz.exportFile(src, root .. "rotorheads\\world.lua", dest)
  if ok then
    world.writeNote("Wrote " .. dest .. "\r\nFrom " .. src .. "\r\nOpen RH_Editor.miz in the Mission Editor. It updates about every 30 seconds while the mission is running.")
  else
    world.writeNote("Editor mission failed.\r\n" .. tostring(err) .. "\r\nSource " .. src)
  end
end

-- DCS's own Esc > Save Mission includes script-spawned units. Attach the campaign so that file can resume the war.
function world.installOfficialSave()
  local dcsWorld = _G.world
  if type(dcsWorld) ~= "table" or type(dcsWorld.setPersistenceHandler) ~= "function" then
    util.log("DCS Save Mission persistence is not in this build")
    return
  end
  dcsWorld.setPersistenceHandler("Rotorheads", function()
    return { campaign = RH.state }
  end)
  util.log("campaign will be stored inside a DCS Save Mission file")
end

function world.readOfficialSave()
  if RH.state.world and RH.state.world.baselineReady then return false end
  local dcsWorld = _G.world
  if type(dcsWorld) ~= "table" or type(dcsWorld.getPersistenceData) ~= "function" then return false end
  local ok, data = pcall(dcsWorld.getPersistenceData, "Rotorheads")
  if not ok or type(data) ~= "table" or type(data.campaign) ~= "table" then return false end
  for k, v in pairs(data.campaign) do RH.state[k] = v end
  util.log("loaded the campaign stored in this mission's DCS save")
  return true
end

function world.restore()
  local saved = RH.state.world
  if not saved or not saved.baselineReady or not RH.dcs.groundRoster then return { spawn = {}, destroy = {}, adopt = {}, refresh = {} } end
  local plan = world.plan(saved, RH.dcs.groundRoster())
  for _, name in ipairs(plan.destroy) do
    if RH.dcs.destroyNamed then RH.dcs.destroyNamed(name) end
  end
  for _, obj in ipairs(plan.refresh) do
    if RH.dcs.destroyNamed then RH.dcs.destroyNamed(obj.name) end
    if RH.dcs.spawnSnapshot then RH.dcs.spawnSnapshot(obj) end
  end
  for _, obj in ipairs(plan.spawn) do
    if RH.dcs.spawnSnapshot then RH.dcs.spawnSnapshot(obj) end
  end
  saved.baseline = saved.baseline or {}
  for _, name in ipairs(plan.adopt) do saved.baseline[name] = true end
  util.log("world restore: %d spawned, %d moved, %d removed, %d new editor units kept",
    #plan.spawn, #plan.refresh, #plan.destroy, #plan.adopt)
  return plan
end

return world

end)
if not __ok then
  env.error("[RH] failed while loading world.lua: " .. tostring(__err))
  trigger.action.outText("ROTORHEADS failed while loading world.lua: " .. tostring(__err), 60)
  return
end end
-- ===== logistics.lua =====
do local __ok, __err = pcall(function()
RH = RH or {}

local util = RH.util

-- FARPs, Logistics Centers (LCs), MASHes, blue outposts and blue zones.
-- FARPs hold a limited stock of generic crates. LCs (a FARP within 1 NM of an airfield) and ships have unlimited crates.
local logistics = {}
RH.logistics = logistics

local function fcfg() return RH.config.farp end
local function mcfg() return RH.config.mash end

-- FARPs ------------------------------------------------------------------------

function logistics.farps()
  local list = {}
  for _, name in ipairs(util.keys(RH.state.farps)) do table.insert(list, RH.state.farps[name]) end
  return list
end

function logistics.register(name, point, opts)
  opts = opts or {}
  local existing = RH.state.farps[name]
  if existing then
    -- The mission-editor zone wins over a saved position, so moving the zone moves the FARP.
    existing.x, existing.y = point.x, point.y
    if opts.zoneRadius then existing.zoneRadius = opts.zoneRadius end
    return existing
  end
  local farp = {
    name = name,
    x = point.x,
    y = point.y,
    lc = opts.lc or false,
    built = opts.built or false,
    airbase = opts.airbase,
    zoneRadius = opts.zoneRadius,
    pending = opts.pending or false,
    crates = opts.crates or (opts.lc and -1 or fcfg().startingCrates),
    liquids = opts.liquids,
    ammoItems = opts.ammoItems,
  }
  RH.state.farps[name] = farp
  return farp
end

function logistics.discoverPlaced()
  local prefix = RH.config.prefixes.farp
  for _, zone in ipairs(RH.dcs.zonesWithPrefix(prefix)) do
    local airbase = logistics.airfieldNear(zone.point, fcfg().lcAirfieldRadius)
    logistics.register(zone.name, zone.point, {
      lc = airbase ~= nil and airbase.coalition ~= "red",
      airbase = airbase and airbase.name,
      zoneRadius = zone.radius,
    })
  end
  logistics.refreshPlacedCenters()
end

-- A mission-editor logistics tent on an airfield is that airfield's Logistics Center.
-- Player-built FARPs are left alone. An existing save is promoted when the tent is close enough.
function logistics.refreshPlacedCenters()
  local radius = fcfg().placedLcRadius or fcfg().lcAirfieldRadius
  for _, farp in pairs(RH.state.farps) do
    if not farp.built and not farp.pending then
      local points = { { x = farp.x, y = farp.y } }
      for _, lp in ipairs(farp.loadPoints or {}) do table.insert(points, lp) end
      for _, p in ipairs(points) do
        local ab = logistics.airfieldNear(p, radius)
        if ab and ab.coalition ~= "red" then
          farp.lc = true
          farp.airbase = ab.name
          farp.crates = -1
          break
        end
      end
    end
  end
end

function logistics.airfieldNear(point, radius)
  local best, bestDist
  for _, ab in ipairs(RH.dcs.airbases()) do
    if ab.kind == "airdrome" and ab.logistics ~= false then
      local d = util.distance(ab.point, point)
      if d <= radius and (not bestDist or d < bestDist) then best, bestDist = ab, d end
    end
  end
  return best
end

function logistics.farpAt(point, radius)
  radius = radius or fcfg().zoneRadius
  local best, bestDist
  for _, farp in pairs(RH.state.farps) do
    local d = util.distance(farp, point)
    local covered = d <= radius
    if not covered then
      for _, lp in ipairs(farp.loadPoints or {}) do
        if util.distance(lp, point) <= fcfg().loadRadius then covered = true break end
      end
    end
    if covered and (not bestDist or d < bestDist) then best, bestDist = farp, d end
  end
  return best
end

function logistics.hasUnlimitedCrates(farp)
  return farp.lc or farp.crates == -1
end

function logistics.takeCrates(farp, n)
  if logistics.hasUnlimitedCrates(farp) then return true end
  if farp.crates < n then return false end
  farp.crates = farp.crates - n
  logistics.refreshMapLabels()
  return true
end

function logistics.isGeneralSupply(name)
  return type(name) == "string" and name:sub(1, #"General supply") == "General supply"
end

-- A normal crate returned at a tent is worth 1. A general-supply crate is worth 5, per the wiki.
function logistics.crateWorth(name)
  if logistics.isGeneralSupply(name) then return fcfg().generalSupplyWorth or RH.config.kits.generalSupply.worth or 5 end
  return 1
end

function logistics.refreshMapLabels()
  if not RH.dcs.drawLabel then return end
  for _, farp in ipairs(logistics.farps()) do
    if farp.pending then
      RH.dcs.drawLabel("farp-stock-" .. farp.name, "blue", farp, farp.name .. "\nbuilds on next restart")
    else
      local crates = logistics.hasUnlimitedCrates(farp) and "unlimited" or tostring(farp.crates or 0)
      RH.dcs.drawLabel("farp-stock-" .. farp.name, "blue", farp, string.format("%s\nCrates: %s", farp.name, crates))
    end
  end
end

function logistics.returnCrates(farp, n)
  if logistics.hasUnlimitedCrates(farp) then return 0 end
  local space = fcfg().maxCrates - farp.crates
  local added = math.max(0, math.min(space, n))
  farp.crates = farp.crates + added
  logistics.refreshMapLabels()
  return added
end

local function airfieldHasLC(airfieldName)
  for _, farp in pairs(RH.state.farps) do
    if farp.lc and farp.airbase == airfieldName then return true end
  end
  return false
end

-- Construction, testing rules:
--  * the first site within 1 NM of a real friendly airfield becomes that airfield's Logistics Center;
--  * helicopter pads such as HS02 are not airfields and cannot be a Logistics Center;
--  * every other site must be at least 1 mile from every FARP and every Logistics Center;
--  * a site within 1 NM of a real airfield that still has no Logistics Center is refused.
function logistics.validateFarpSite(point)
  local airfield = logistics.airfieldNear(point, fcfg().lcAirfieldRadius)
  if airfield and airfield.coalition == "red" then
    return false, airfield.name .. " is still held by REDFOR"
  end
  if airfield and not airfieldHasLC(airfield.name) then
    return true, "lc", airfield
  end

  local mile = fcfg().minSeparation
  for _, farp in pairs(RH.state.farps) do
    local d = util.distance(farp, point)
    if d < mile then
      local what = farp.lc and "Logistics Center" or "FARP"
      return false, string.format("%.2f miles from %s %s (needs 1 mile)", d / mile, what, farp.name)
    end
  end

  for _, ab in ipairs(RH.dcs.airbases()) do
    if ab.kind == "airdrome" and ab.logistics ~= false and util.distance(ab.point, point) < fcfg().minDistanceFarp and not airfieldHasLC(ab.name) then
      return false, "within 1 NM of " .. ab.name .. ", which has no Logistics Center yet"
    end
  end
  return true, "farp"
end

function logistics.nextFarpName(kind, airfield)
  if kind == "lc" then return "LC " .. airfield.name end
  local n = 1
  for _, farp in pairs(RH.state.farps) do
    if not farp.lc and (farp.built or farp.pending) then n = n + 1 end
  end
  return string.format("FARP %02d", n)
end

-- Marks the site. DCS cannot stand up a working FARP in the running mission, so it appears on the next restart.
function logistics.buildFarp(point, builtBy)
  local ok, kind, airfield = logistics.validateFarpSite(point)
  if not ok then return nil, kind end
  local name = logistics.nextFarpName(kind, airfield)
  local farp = logistics.register(name, point, {
    lc = kind == "lc",
    built = false,
    pending = true,
    airbase = airfield and airfield.name,
    crates = kind == "lc" and -1 or 0,
  })
  RH.dcs.drawCircle("pending-" .. name, "blue", farp, 600, { 0, 0.7, 1, 1 }, { 0, 0.7, 1, 0.15 }, name .. " (next restart)")
  RH.dcs.smoke(farp, RH.config.markers.smokeColors.green)
  if RH.persistence and RH.persistence.save then RH.persistence.save() end
  RH.dcs.message("blue", string.format(
    "%s marked %s and saved it. Restart the mission to build the pad, tent, Humvee, fuel depot, and ammo dump. The Mission Editor copy is RH_Editor.miz, written beside your mission when you leave.",
    builtBy or "A pilot", name), 30)
  RH.dcs.notify("farp_marked", { farp = name, kind = kind })
  return farp
end

-- Spawn every FARP that was marked on an earlier run. Fuel and ammo come from the save, which is empty the first time.
function logistics.farpNear(point, radius)
  local best, bestDist
  for _, farp in pairs(RH.state.farps) do
    if (farp.pending or farp.built) and not farp.lc then
      local d = util.distance(farp, point)
      if d <= radius and (not bestDist or d < bestDist) then best, bestDist = farp, d end
    end
  end
  return best
end

function logistics.spawnBuilt()
  logistics.sessionSpawned = {}
  local marked = {}
  for _, farp in pairs(RH.state.farps) do
    if farp.pending or farp.built then table.insert(marked, farp) end
  end
  if #marked == 0 then
    RH.dcs.message("blue", "No marked FARP in the save.", 20)
    return
  end
  for _, farp in ipairs(marked) do
    local ok, err = pcall(RH.dcs.spawnFarp, farp)
    if ok then
      logistics.sessionSpawned[farp.name] = true
      farp.pending = false
      farp.built = true
      RH.dcs.removeDrawing("pending-" .. farp.name)
      local stock = logistics.hasWarehouseStock(farp) and "Fuel and ammo restored from the save." or "No fuel or ammo yet."
      RH.dcs.message("blue", farp.name .. " is up. Dynamic spawn. " .. stock, 25)
    else
      util.log("spawn %s failed: %s", farp.name, tostring(err))
      RH.dcs.message("blue", string.format("%s is in the save but did not spawn: %s", farp.name, tostring(err)), 30)
    end
  end
end

function logistics.captureStocks()
  if RH.dcs.captureFarpStock then
    for name in pairs(logistics.sessionSpawned or {}) do
      local farp = RH.state.farps[name]
      if farp then RH.dcs.captureFarpStock(farp) end
    end
  end
  logistics.capturePads()
end

-- One load for the editor pads (static1-4 and static1-5). Later restarts write the
-- saved figures back and do not add another 10 tons or another 40 missiles.
logistics.padHold = {}

function logistics.openingPadStock()
  return {
    fuelKg = 10000,
    missiles = {
      ["weapons.missiles.AGM_114K"] = 40,
      ["weapons.missiles.AGM_114L"] = 40,
      ["weapons.missiles.Vikhr_M"] = 40,
    },
  }
end

function logistics.ensurePadStock(name)
  RH.state.padStock = RH.state.padStock or {}
  local saved = RH.state.padStock[name]
  if type(saved) == "table" and saved.granted and type(saved.fuelKg) == "number" and type(saved.missiles) == "table" then
    return saved, false
  end
  local stock = logistics.openingPadStock()
  stock.granted = true
  RH.state.padStock[name] = stock
  return stock, true
end

function logistics.syncPads()
  if not RH.dcs.farpPads or not RH.dcs.writePadStock then return end
  local fresh = {}
  for _, name in ipairs(RH.dcs.farpPads()) do
    local stock, granted = logistics.ensurePadStock(name)
    RH.dcs.writePadStock(name, stock)
    if logistics.padHold[name] == nil then logistics.padHold[name] = RH.dcs.now() + 25 end
    if granted then fresh[#fresh + 1] = name end
  end
  if #fresh > 0 then
    RH.dcs.message("blue", "One-time FARP stock, 10 tons of fuel and 40 AGM-114K, AGM-114L, and Vikhr: " .. table.concat(fresh, ", "), 30)
  end
end

function logistics.capturePads()
  if not RH.dcs.readPadStock then return end
  RH.state.padStock = RH.state.padStock or {}
  for name, saved in pairs(RH.state.padStock) do
    if type(saved) == "table" and saved.granted and not (logistics.padHold[name] and RH.dcs.now() < logistics.padHold[name]) then
      local live = RH.dcs.readPadStock(name, saved.missiles)
      if live then
        live.granted = true
        RH.state.padStock[name] = live
      end
    end
  end
end

