    if RH.dcs.spawnGroup(tpl[math.random(#tpl)], util.randomPointInCircle(zone.point, radius), "Paratroopers") then
      spawned = spawned + 1
    end
  end
  util.log("paratroopers: %d groups dropped", spawned)
  return spawned
end

